package com.loopers.infrastructure.event;import com.loopers.domain.event.OutboxPublisher;import lombok.RequiredArgsConstructor;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Component;@Component @RequiredArgsConstructor public class KafkaOutboxPublisher implements OutboxPublisher{private final KafkaTemplate<Object,Object> kafka;public void publish(String eventId,String payload){kafka.send("order-confirmed",eventId,payload).join();}}
